#include "scarlett_imports64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;ScarlettImports64 h;assert(h.install(m));assert(m.map(0x10000,4096,3)==GuestMemory64::Fault::none);uint64_t r=0;auto call=[&](const char*d,const char*n,uint64_t a=0,uint64_t b=0){auto p=h.registerImport(d,n);assert(p&&h.dispatch(p,m,a,r,b));return r;};const char*f="api-ms-win-core-fibers-l1-1-0.dll";auto i=call(f,"FlsAlloc");assert(i==0);assert(call(f,"FlsSetValue",i,42)==1);h.selectThread(2,0);assert(call(f,"FlsGetValue",i)==0);h.selectThread(1,0);assert(call(f,"FlsGetValue",i)==42);assert(call(f,"FlsFree",i)==1);assert(call(f,"FlsAlloc",1)==UINT32_MAX);const char*u="api-ms-win-core-util-l1-1-0.dll";auto enc=call(u,"EncodePointer",123);assert(call(u,"DecodePointer",enc)==123);assert(m.write(0x10000,std::vector<uint8_t>{'-','4','2',0})==GuestMemory64::Fault::none);assert(call("api-ms-win-crt-convert-l1-1-0.dll","atol",0x10000)==uint32_t(-42));h.setImageBase(0x140000000);h.setExceptionDirectory(4096,0,0);assert(call("api-ms-win-core-rtlsupport-l1-1-0.dll","RtlPcToFileHeader",0x140000010,0x10100)==0x140000000);std::cout<<"V85D tests passed\n";}
